/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: "Benchmark cohort selection",
        value: {
            "cohortName": event.payload.items[0].label
        }
    };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	var items = [];
    if (api.state.selectedCohortID)
        items.push(api.state.selectedCohortID);
    else
        items.push(
           'all'
        );
    return items;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: "Benchmark category selection",
        value: {
            "categoryName": event.payload.items[0].label
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var items = [];
    for (var i = 0; i < api.state.categories.length; i++) {
        items.push({
            "id": api.state.categories[i].id,
            "label": api.state.categories[i].label
        });
    }
    return items;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var items = [];
    if (api.state.selectedCategory)
        items.push(api.state.selectedCategory);
    else
        items.push(
            api.state.categories[0].id
        );
    return items;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: "Benchmark dashboard tab views",
        value: {
            "tabName": api.state.tabs[event.payload.selectedTabIndex].label
        }
    };
}
